package com.PartyPotionTracker;

import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ItemSpawned;
import net.runelite.client.party.PartyService;

public class DropManager {
    private Client client;
    private PartyService partyService;

    public DropManager(Client client, PartyService partyService) {
        this.client = client;
        this.partyService = partyService;
    }


    public TrackedItem itemSpawned(ItemSpawned event) {

        TileItem item = event.getItem();
        int itemId = item.getId();

        if (!RaidPotions.isPotion(itemId)) {
            return null;
        }

        if (item.getOwnership() != TileItem.OWNERSHIP_SELF
                || client.getLocalPlayer() == null) {
            return null;
        }

        WorldPoint spawnLocation = event.getTile().getWorldLocation();
        if (spawnLocation == null) {
            return null;
        }

        String ownerName = client.getLocalPlayer().getName();
        TrackedItem trackedItem = new TrackedItem(itemId, spawnLocation, ownerName);

        if (partyService != null && partyService.isInParty()) {
            partyService.send(new TrackedItemMessage(itemId, spawnLocation, ownerName));
        }

        return trackedItem;
    }
}

package com.PartyPotionTracker;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.EqualsAndHashCode;
import lombok.NoArgsConstructor;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.party.messages.PartyMemberMessage;

@EqualsAndHashCode(callSuper = false)
@Data
@NoArgsConstructor
@AllArgsConstructor
public class PickedUpItemMessage extends PartyMemberMessage {
    private int itemId;
    private WorldPoint worldPoint;
    private String pickerName;
}

package com.PartyPotionTracker;

import lombok.Getter;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.party.PartyService;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CopyOnWriteArrayList;

public class PickupManager
{
    private static final int EXPECTED_PICKUP_TIMEOUT_TICKS = 5;

    static class ExpectedPickup
    {
        final int itemId;
        final WorldPoint location;
        final String playerName;
        final int createdTick;

        ExpectedPickup(int itemId, WorldPoint location, String playerName, int createdTick)
        {
            this.itemId = itemId;
            this.location = location;
            this.playerName = playerName;
            this.createdTick = createdTick;
        }
    }

    static class PendingDespawn
    {
        final int itemId;
        final WorldPoint location;

        PendingDespawn(int itemId, WorldPoint location)
        {
            this.itemId = itemId;
            this.location = location;
        }
    }

    private final Client client;
    private final PartyService partyService;
    private final ClientThread clientThread;

    private ExpectedPickup expectedPickup;

    /**
     * Owner metadata for potion ground items. The overlay only draws a record
     * when the corresponding ground item is currently present in the scene.
     */
    @Getter
    private final List<TrackedItem> myDroppedItems = new CopyOnWriteArrayList<>();

    private final List<PendingDespawn> pendingDespawns = new CopyOnWriteArrayList<>();

    private Map<Integer, Integer> previousInventory;

    public PickupManager(Client client, PartyService partyService, ClientThread clientThread)
    {
        this.client = client;
        this.partyService = partyService;
        this.clientThread = clientThread;
    }

    public void clear()
    {
        myDroppedItems.clear();
        pendingDespawns.clear();
        previousInventory = null;
        expectedPickup = null;
    }

    public void gameTick()
    {
        if (expectedPickup != null
                && client.getTickCount() - expectedPickup.createdTick > EXPECTED_PICKUP_TIMEOUT_TICKS)
        {
            expectedPickup = null;
        }

        processPendingDespawns();
    }

    /**
     * ItemDespawned describes a change to the currently loaded scene. It is
     * not safe to remove metadata immediately because scene rebuilds can emit
     * the same event while a potion still exists in the raid.
     */
    public void itemDespawned(int itemId, WorldPoint location)
    {
        if (location == null || findTrackedItem(itemId, location) == null)
        {
            return;
        }

        for (PendingDespawn pending : pendingDespawns)
        {
            if (pending.itemId == itemId && pending.location.equals(location))
            {
                return;
            }
        }

        pendingDespawns.add(new PendingDespawn(itemId, location));
    }

    public void trackDrop(TrackedItem item)
    {
        if (item == null || item.getWorldPoint() == null || !RaidPotions.isPotion(item.getItemId()))
        {
            return;
        }

        TrackedItem existing = findTrackedItem(item.getItemId(), item.getWorldPoint());
        if (existing != null)
        {
            if (equalsIgnoreCase(existing.getOwnerName(), item.getOwnerName()))
            {
                return;
            }

            myDroppedItems.remove(existing);
        }

        myDroppedItems.add(item);
    }

    public TrackedItem findTrackedItem(int itemId, WorldPoint location)
    {
        if (location == null)
        {
            return null;
        }

        for (TrackedItem item : myDroppedItems)
        {
            if (item.matches(itemId, location))
            {
                return item;
            }
        }

        return null;
    }

    private void removeTrackedItem(int itemId, WorldPoint location)
    {
        TrackedItem trackedItem = findTrackedItem(itemId, location);
        if (trackedItem != null)
        {
            myDroppedItems.remove(trackedItem);
        }

        pendingDespawns.removeIf(pending -> pending.itemId == itemId
                && pending.location.equals(location));
    }

    public void onPickedUpItemMessage(PickedUpItemMessage message)
    {
        TrackedItem trackedItem = findTrackedItem(message.getItemId(), message.getWorldPoint());
        if (trackedItem == null)
        {
            return;
        }

        myDroppedItems.remove(trackedItem);
        pendingDespawns.removeIf(pending -> pending.itemId == message.getItemId()
                && pending.location.equals(message.getWorldPoint()));

        // Only report a pickup by somebody other than the owner. The owner
        // already knows they picked up their own potion.
        if (!equalsIgnoreCase(trackedItem.getOwnerName(), message.getPickerName()))
        {
            clientThread.invokeLater(() ->
            {
                String itemName = client.getItemDefinition(message.getItemId()).getName();
                String chatMessage = String.format(
                        "%s picked up a %s dropped by %s!",
                        message.getPickerName(),
                        itemName,
                        trackedItem.getOwnerName());
                client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", chatMessage, null);
            });
        }
    }

    public void menuOptionClicked(MenuOptionClicked event)
    {
        if (!"Take".equalsIgnoreCase(event.getMenuOption()))
        {
            expectedPickup = null;
            return;
        }

        int itemId = event.getId();
        if (!RaidPotions.isPotion(itemId))
        {
            return;
        }

        WorldPoint location = getInteractionLocation(event);
        if (location == null || client.getLocalPlayer() == null)
        {
            return;
        }

        expectedPickup = new ExpectedPickup(
                itemId,
                location,
                client.getLocalPlayer().getName(),
                client.getTickCount());
    }

    public void itemContainerChanged(ItemContainerChanged event)
    {
        if (event.getContainerId() != InventoryID.INVENTORY.getId())
        {
            return;
        }

        Map<Integer, Integer> currentInventory = snapshot(event.getItemContainer());
        if (previousInventory == null)
        {
            previousInventory = currentInventory;
            return;
        }

        ExpectedPickup pickup = expectedPickup;
        if (pickup != null)
        {
            int oldQuantity = previousInventory.getOrDefault(pickup.itemId, 0);
            int newQuantity = currentInventory.getOrDefault(pickup.itemId, 0);

            if (newQuantity > oldQuantity)
            {
                removeTrackedItem(pickup.itemId, pickup.location);

                if (partyService != null && partyService.isInParty())
                {
                    partyService.send(new PickedUpItemMessage(
                            pickup.itemId,
                            pickup.location,
                            pickup.playerName));
                }

                expectedPickup = null;
            }
        }

        previousInventory = currentInventory;
    }

    private WorldPoint getInteractionLocation(MenuOptionClicked event)
    {
        WorldView worldView = client.getTopLevelWorldView();
        if (worldView != null && worldView.getScene() != null)
        {
            Tile[][][] tiles = worldView.getScene().getTiles();
            int plane = worldView.getPlane();
            int sceneX = event.getParam0();
            int sceneY = event.getParam1();

            if (plane >= 0 && plane < tiles.length
                    && sceneX >= 0 && sceneX < tiles[plane].length
                    && sceneY >= 0 && sceneY < tiles[plane][sceneX].length
                    && tiles[plane][sceneX][sceneY] != null)
            {
                return tiles[plane][sceneX][sceneY].getWorldLocation();
            }

            Tile selectedTile = worldView.getSelectedSceneTile();
            if (selectedTile != null)
            {
                return selectedTile.getWorldLocation();
            }
        }

        return null;
    }

    private void processPendingDespawns()
    {
        for (PendingDespawn pending : pendingDespawns)
        {
            Tile currentTile = getLoadedTile(pending.location);
            if (currentTile == null)
            {
                // The tile is outside the current scene. Keep the metadata so
                // it can be used if the player walks back into render range.
                continue;
            }

            boolean stillPresent = currentTile.getGroundItems() != null
                    && currentTile.getGroundItems().stream()
                    .anyMatch(item -> item.getId() == pending.itemId);

            if (!stillPresent)
            {
                removeTrackedItem(pending.itemId, pending.location);
            }
            else
            {
                pendingDespawns.remove(pending);
            }
        }
    }

    private Tile getLoadedTile(WorldPoint location)
    {
        WorldView worldView = client.getTopLevelWorldView();
        if (worldView == null || worldView.getScene() == null)
        {
            return null;
        }

        LocalPoint localPoint = LocalPoint.fromWorld(worldView, location);
        if (localPoint == null || !localPoint.isInScene())
        {
            return null;
        }

        Tile[][][] tiles = worldView.getScene().getTiles();
        int plane = worldView.getPlane();
        int sceneX = localPoint.getSceneX();
        int sceneY = localPoint.getSceneY();
        if (plane < 0 || plane >= tiles.length
                || sceneX < 0 || sceneX >= tiles[plane].length
                || sceneY < 0 || sceneY >= tiles[plane][sceneX].length)
        {
            return null;
        }

        return tiles[plane][sceneX][sceneY];
    }

    private static Map<Integer, Integer> snapshot(ItemContainer container)
    {
        Map<Integer, Integer> snapshot = new HashMap<>();
        if (container == null)
        {
            return snapshot;
        }

        for (Item item : container.getItems())
        {
            if (item.getId() >= 0)
            {
                snapshot.merge(item.getId(), item.getQuantity(), Integer::sum);
            }
        }

        return snapshot;
    }

    private static boolean equalsIgnoreCase(String first, String second)
    {
        return first == null ? second == null : first.equalsIgnoreCase(second);
    }
}

package com.PartyPotionTracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("PotionTrackerConfig")
public interface PotionTrackerConfig extends Config{
    String HIGHLIGHT_SECTION = "highlightSection";

    @ConfigSection(
            name = "Potion highlighting",
            description = "Controls which ground potions are highlighted and how they look",
            position = 0
    )
    String highlightSection = "highlightSection";

    @ConfigItem(
            keyName = "highlightOwnPotions",
            name = "Highlight my potions",
            description = "Highlight potions dropped by you",
            section = HIGHLIGHT_SECTION,
            position = 1
    )
    default boolean highlightOwnPotions(){
        return true;
    }

    @ConfigItem(
            keyName = "highlightPartyPotions",
            name = "Highlight party potions",
            description = "Highlight potions associated with a party member",
            section = HIGHLIGHT_SECTION,
            position = 2
    )
    default boolean highlightPartyPotions(){
        return true;
    }

    @ConfigItem(
            keyName = "highlightUnknownPotions",
            name = "Highlight unknown potions",
            description = "Highlight potion ground items whose owner is not known",
            section = HIGHLIGHT_SECTION,
            position = 3
    )
    default boolean highlightUnknownPotions(){
        return false;
    }

    @ConfigItem(
            keyName = "highlightStyle",
            name = "Highlight style",
            description = "How a potion is drawn on the ground",
            section = HIGHLIGHT_SECTION,
            position = 4
    )
    default HighlightStyle highlightStyle(){
        return HighlightStyle.ITEM_OUTLINE;
    }

    @Range(min = 1, max = 6)
    @ConfigItem(
            keyName = "outlineWidth",
            name = "Outline width",
            description = "Width of the potion model outline and geometric markers",
            section = HIGHLIGHT_SECTION,
            position = 5
    )
    default int outlineWidth(){
        return 2;
    }

    enum HighlightStyle
    {
        ITEM_OUTLINE,
        DOT,
        CORNERS;

        @Override
        public String toString()
        {
            switch (this)
            {
                case ITEM_OUTLINE:
                    return "Potion outline";
                case CORNERS:
                    return "Corner markers";
                case DOT:
                default:
                    return "Dot";
            }
        }
    }
}

package com.PartyPotionTracker;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

import javax.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Stroke;

public class PotionTrackerOverlay extends Overlay
{
    private static final Color UNKNOWN_COLOR = Color.LIGHT_GRAY;
    private static final int OUTLINE_ALPHA = 220;

    private final Client client;
    private final PotionTrackerPlugin plugin;
    private final ModelOutlineRenderer modelOutlineRenderer;

    @Inject
    public PotionTrackerOverlay(Client client, PotionTrackerPlugin plugin, ModelOutlineRenderer modelOutlineRenderer)
    {
        this.client = client;
        this.plugin = plugin;
        this.modelOutlineRenderer = modelOutlineRenderer;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!plugin.isInRaid() || client.getLocalPlayer() == null)
        {
            return null;
        }

        WorldView worldView = client.getTopLevelWorldView();
        if (worldView == null || worldView.getScene() == null)
        {
            return null;
        }

        Scene scene = worldView.getScene();
        Tile[][][] tiles = scene.getTiles();
        if (tiles == null)
        {
            return null;
        }

        Color previousColor = graphics.getColor();
        Stroke previousStroke = graphics.getStroke();
        Composite previousComposite = graphics.getComposite();

        try
        {
            for (int plane = 0; plane < tiles.length; plane++)
            {
                if (tiles[plane] == null)
                {
                    continue;
                }

                for (Tile[] row : tiles[plane])
                {
                    if (row == null)
                    {
                        continue;
                    }

                    for (Tile tile : row)
                    {
                        renderTile(graphics, tile);
                    }
                }
            }
        }
        finally
        {
            graphics.setColor(previousColor);
            graphics.setStroke(previousStroke);
            graphics.setComposite(previousComposite);
        }

        return null;
    }

    private void renderTile(Graphics2D graphics, Tile tile)
    {
        if (tile == null || tile.getGroundItems() == null || tile.getLocalLocation() == null)
        {
            return;
        }

        WorldPoint location = tile.getWorldLocation();
        if (location == null)
        {
            return;
        }

        for (TileItem item : tile.getGroundItems())
        {
            if (!RaidPotions.isPotion(item.getId()))
            {
                continue;
            }

            TrackedItem trackedItem = plugin.getPickupManager().findTrackedItem(item.getId(), location);
            HighlightKind kind = getHighlightKind(item, trackedItem);
            if (!isEnabled(kind))
            {
                continue;
            }

            Color color = getColor(kind, trackedItem);
            drawHighlight(graphics, tile, tile.getLocalLocation(), item, color);
        }
    }

    private HighlightKind getHighlightKind(TileItem item, TrackedItem trackedItem)
    {
        if (item.getOwnership() == TileItem.OWNERSHIP_SELF
                || isLocalOwner(trackedItem))
        {
            return HighlightKind.OWN;
        }

        if (trackedItem != null)
        {
            return HighlightKind.PARTY;
        }

        return HighlightKind.UNKNOWN;
    }

    private boolean isLocalOwner(TrackedItem trackedItem)
    {
        return trackedItem != null
                && trackedItem.getOwnerName() != null
                && client.getLocalPlayer() != null
                && trackedItem.getOwnerName().equalsIgnoreCase(client.getLocalPlayer().getName());
    }

    private boolean isEnabled(HighlightKind kind)
    {
        switch (kind)
        {
            case OWN:
                return plugin.getConfig().highlightOwnPotions();
            case PARTY:
                return plugin.getConfig().highlightPartyPotions();
            case UNKNOWN:
                return plugin.getConfig().highlightUnknownPotions();
            default:
                return false;
        }
    }

    private Color getColor(HighlightKind kind, TrackedItem trackedItem)
    {
        if (kind == HighlightKind.OWN)
        {
            String ownerName = trackedItem == null || trackedItem.getOwnerName() == null
                    ? client.getLocalPlayer() == null ? null : client.getLocalPlayer().getName()
                    : trackedItem.getOwnerName();
            return plugin.getColorForPartyMember(ownerName);
        }

        if (kind == HighlightKind.PARTY && trackedItem != null)
        {
            return plugin.getColorForPartyMember(trackedItem.getOwnerName());
        }

        return UNKNOWN_COLOR;
    }

    private void drawHighlight(
            Graphics2D graphics,
            Tile tile,
            LocalPoint localPoint,
            TileItem item,
            Color color)
    {
        PotionTrackerConfig.HighlightStyle style = plugin.getConfig().highlightStyle();
        switch (style)
        {
            case ITEM_OUTLINE:
                drawItemOutline(graphics, tile, item, localPoint, color);
                break;
            case DOT:
                drawDot(graphics, localPoint, color);
                break;
            case CORNERS:
                drawCornerMarkers(graphics, localPoint, color);
                break;
            default:
                drawItemOutline(graphics, tile, item, localPoint, color);
                break;
        }
    }

    private void drawItemOutline(
            Graphics2D graphics,
            Tile tile,
            TileItem item,
            LocalPoint localPoint,
            Color color)
    {
        if (tile.getItemLayer() != null && item != null)
        {
            modelOutlineRenderer.drawOutline(
                    tile.getItemLayer(),
                    item,
                    plugin.getConfig().outlineWidth(),
                    color,
                    4);
            return;
        }

        // The model layer can be absent during a scene rebuild. There is no
        // tile-fill fallback because tile highlighting is intentionally removed.
    }

    private void drawCornerMarkers(Graphics2D graphics, LocalPoint localPoint, Color color)
    {
        Polygon tilePolygon = Perspective.getCanvasTilePoly(client, localPoint);
        if (tilePolygon == null || tilePolygon.npoints < 2)
        {
            return;
        }

        graphics.setColor(withAlpha(color, OUTLINE_ALPHA));
        graphics.setStroke(new BasicStroke(plugin.getConfig().outlineWidth()));

        for (int i = 0; i < tilePolygon.npoints; i++)
        {
            int next = (i + 1) % tilePolygon.npoints;
            int previous = (i + tilePolygon.npoints - 1) % tilePolygon.npoints;
            int x = tilePolygon.xpoints[i];
            int y = tilePolygon.ypoints[i];

            drawCornerSegment(graphics, x, y,
                    tilePolygon.xpoints[next], tilePolygon.ypoints[next]);
            drawCornerSegment(graphics, x, y,
                    tilePolygon.xpoints[previous], tilePolygon.ypoints[previous]);
        }
    }

    private void drawCornerSegment(Graphics2D graphics, int startX, int startY, int endX, int endY)
    {
        int cornerLength = 4;
        int x = startX + (endX - startX) / cornerLength;
        int y = startY + (endY - startY) / cornerLength;
        graphics.drawLine(startX, startY, x, y);
    }

    private void drawDot(Graphics2D graphics, LocalPoint localPoint, Color color)
    {
        Point canvasPoint = Perspective.localToCanvas(client, localPoint, 0);
        if (canvasPoint == null)
        {
            return;
        }

        int radius = 4;
        graphics.setColor(withAlpha(color, OUTLINE_ALPHA));
        graphics.fillOval(canvasPoint.getX() - radius, canvasPoint.getY() - radius, radius * 2, radius * 2);
    }

    private static Color withAlpha(Color color, int alpha)
    {
        return new Color(color.getRed(), color.getGreen(), color.getBlue(), alpha);
    }

    private enum HighlightKind
    {
        OWN,
        PARTY,
        UNKNOWN
    }
}

package com.PartyPotionTracker;

import javax.inject.Inject;

import com.google.inject.Provides;
import lombok.AccessLevel;
import lombok.Getter;
import net.runelite.api.*;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.*;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.party.PartyService;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.party.PartyPlugin;
import net.runelite.client.plugins.party.PartyPluginService;
import net.runelite.client.plugins.party.data.PartyMemberData;
import net.runelite.client.ui.overlay.OverlayManager;
import java.awt.*;
import net.runelite.client.party.WSClient;




@PluginDependency(PartyPlugin.class)
@PluginDescriptor(
	name = "Party Potion Tracker",
		 description = "Tracks and highlights raid supplies dropped in parties, and shows who picks them up",
		tags = {"potion", "party", "toa", "tob", "tfa", "cox", "team", "tracker"}
)
public class PotionTrackerPlugin extends Plugin
{
	@Inject
	private WSClient wsClient;

	@Inject
	private Client client;

	@Inject
	private PartyService partyService;

	@Inject
	private ConfigManager configManager;

	@Getter(AccessLevel.PACKAGE)
	@Inject
	private PartyPluginService partyPluginService;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private PotionTrackerOverlay overlay;

	@Inject
	private net.runelite.client.callback.ClientThread clientThread;

	@Getter
	@Inject
	private PotionTrackerConfig config;

	@Getter
	private PickupManager pickupManager;
	private DropManager dropManager;

	private boolean inRaid = false;


	@Provides
	PotionTrackerConfig provideConfig(ConfigManager configManager) {
		return configManager.getConfig(PotionTrackerConfig.class);
	}

	@Override
	protected void startUp() throws Exception
	{
		migrateRemovedHighlightStyles();
		dropManager = new DropManager(client, partyService);
		pickupManager = new PickupManager(client, partyService, clientThread);
		wsClient.registerMessage(TrackedItemMessage.class);
		wsClient.registerMessage(PickedUpItemMessage.class);
		overlayManager.add(overlay);
	}

	private void migrateRemovedHighlightStyles()
	{
		String savedStyle = configManager.getConfiguration("PotionTrackerConfig", "highlightStyle");
		if ("TILE_OUTLINE".equals(savedStyle)
				|| "TILE_FILL".equals(savedStyle)
				|| "CIRCLE".equals(savedStyle))
		{
			configManager.setConfiguration(
					"PotionTrackerConfig",
					"highlightStyle",
					PotionTrackerConfig.HighlightStyle.ITEM_OUTLINE.name());
		}
	}

	@Override
	protected void shutDown() throws Exception
	{

		// Clean up
		overlayManager.remove(overlay);
		wsClient.unregisterMessage(PickedUpItemMessage.class);
		wsClient.unregisterMessage(TrackedItemMessage.class);
	}

	@Subscribe
	public void onTrackedItemMessage(TrackedItemMessage msg) {
		if (!inRaid || msg.getWorldPoint() == null || !RaidPotions.isPotion(msg.getItemId())) {
			return;
		}

		pickupManager.trackDrop(new TrackedItem(msg.getItemId(), msg.getWorldPoint(), msg.getOwnerName()));
	}


	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event) {
		if (inRaid){
			pickupManager.menuOptionClicked(event);
		}
	}

	@Subscribe
	public void onPickedUpItemMessage(PickedUpItemMessage msg) {
		if (inRaid) {
			pickupManager.onPickedUpItemMessage(msg);
		}
	}

	@Subscribe
	public void onItemDespawned(ItemDespawned event) {
		if (inRaid) {
			pickupManager.itemDespawned(
					event.getItem().getId(),
					event.getTile().getWorldLocation());
		}
	}


	@Subscribe
	public void onGameStateChanged(GameStateChanged gameState) {
		if (gameState.getGameState().equals(GameState.LOADING)){
			pickupManager.clear();
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick) {
		if (client.getLocalPlayer() == null) {
			if (inRaid) {
				pickupManager.clear();
			}
			inRaid = false;
			return;
		}

		LocalPoint lp = client.getLocalPlayer().getLocalLocation();
		WorldPoint mappedPoint = lp == null ? null : WorldPoint.fromLocalInstance(client, lp);
		int regionId = mappedPoint == null ? -1 : mappedPoint.getRegionID();
		RaidRegion currentRegion = RaidRegion.fromRegionId(regionId);
		boolean wasInRaid = inRaid;
		inRaid = currentRegion != null;
		if (wasInRaid && !inRaid) {
			pickupManager.clear();
		}

		if (inRaid){
			pickupManager.gameTick();
		}
	}

	@Subscribe
	public void onItemSpawned(ItemSpawned event) {
		if (inRaid){
			TrackedItem trackedItem = dropManager.itemSpawned(event);
			if (trackedItem != null) {
				pickupManager.trackDrop(trackedItem);
			}
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event) {
		if (inRaid) {
			pickupManager.itemContainerChanged(event);
		}
	}

	public Color getColorForPartyMember(String name)
	{
		if (name == null) {
			return Color.LIGHT_GRAY;
		}

		PartyMemberData data = null;
		if (partyService != null && partyService.isInParty() && partyPluginService != null){
			net.runelite.client.party.PartyMember member = partyService.getMemberByDisplayName(name);
			if (member != null) {
				data = partyPluginService.getPartyData(member.getMemberId());
			}
		}

		if (data != null && data.getColor() != null){
			return data.getColor();
		}

		return Color.LIGHT_GRAY;
	}

	boolean isInRaid()
	{
		return inRaid;
	}
}

package com.PartyPotionTracker;

import java.util.HashMap;
import java.util.Map;

/**
 * Region IDs for the supported instanced raid areas. The overlay is still
 * restricted to these regions so normal-world potions are never highlighted.
 */
public enum RaidRegion
{
    // Chambers of Xeric, including challenge-mode rooms.
    COX(12889, 13136, 13137, 13138, 13139, 13140, 13141, 13145,
            13393, 13394, 13395, 13396, 13397, 13401),

    // Theatre of Blood, including entry and hard-mode room regions.
    TOB(12611, 12612, 12613, 12867, 12869, 13122, 13123, 13125, 13379),

    // Tombs of Amascut, including the lobby/chest-room regions.
    TOA(14160, 14162, 14164, 14672, 14674, 14676, 15184, 15186,
            15188, 15696, 15698, 15700),

    // The Fractured Archive (Raids 4).
    TFA(16214, 16726, 16215, 16727, 16216, 16728, 16471, 16472, 16474);

    private static final Map<Integer, RaidRegion> REGION_MAP = new HashMap<>();

    static
    {
        for (RaidRegion raidRegion : values())
        {
            for (int regionId : raidRegion.regionIds)
            {
                REGION_MAP.put(regionId, raidRegion);
            }
        }
    }

    private final int[] regionIds;

    RaidRegion(int... regionIds)
    {
        this.regionIds = regionIds;
    }

    public static RaidRegion fromRegionId(int regionId)
    {
        return REGION_MAP.get(regionId);
    }
}

package com.PartyPotionTracker;

import lombok.EqualsAndHashCode;
import lombok.Getter;
import net.runelite.api.coords.WorldPoint;

@Getter
@EqualsAndHashCode
public class TrackedItem
{
    private final int itemId;
    private final WorldPoint worldPoint;
    private final String ownerName;

    public TrackedItem(int itemId, WorldPoint worldPoint, String ownerName){
        this.itemId = itemId;
        this.worldPoint = worldPoint;
        this.ownerName = ownerName;
    }

    public boolean matches(int itemId, WorldPoint worldPoint)
    {
        return this.itemId == itemId
                && this.worldPoint != null
                && this.worldPoint.equals(worldPoint);
    }
}

